def earliest_ready_day(ready, k, m):
    if m * k > len(ready):
        return -1

    def blocks(day):
        count = run = 0
        for r in ready:
            if r <= day:
                run += 1
                if run == k:
                    count += 1
                    run = 0
            else:
                run = 0
        return count

    lo, hi = min(ready), max(ready)
    while lo < hi:
        mid = (lo + hi) // 2
        if blocks(mid) >= m:
            hi = mid
        else:
            lo = mid + 1
    return lo

